create role anon;
create role authenticated;
create schema auth;
create schema app_private;
grant usage on schema public,auth,app_private to authenticated;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function app_private.person_is_accessible(person_id uuid) returns boolean language sql stable as $$ select person_id=auth.uid() $$;
create function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table public.people(id uuid primary key);
create table public.exercises(id uuid primary key);
create table public.sessions(id uuid primary key default gen_random_uuid(),person_id uuid not null references public.people,session_date date,title text,completed boolean,created_at timestamptz default now());
create table public.program_assignments(id uuid primary key, person_id uuid, current_workout_index integer, prescription jsonb);
create table public.suggested_workouts(id uuid primary key,person_id uuid references public.people,mobility_practice_run_id uuid,plan_kind text,program_workout_id uuid,status text,suggested_for date,completed_session_id uuid references public.sessions);
create function public.save_workout(uuid,jsonb,jsonb,jsonb) returns uuid language sql as $$select gen_random_uuid()$$;
alter table public.sessions enable row level security;
create policy owner on public.sessions for all to authenticated using(app_private.person_is_accessible(person_id)) with check(app_private.person_is_accessible(person_id));
alter table public.suggested_workouts enable row level security;
create policy owner on public.suggested_workouts for all to authenticated using(app_private.person_is_accessible(person_id)) with check(app_private.person_is_accessible(person_id));
grant select,insert,update on public.sessions,public.suggested_workouts to authenticated;
grant select on public.people,public.exercises to authenticated;
